package com.luis.artelyapp.ui.theme
import androidx.compose.ui.graphics.Color
// Colores principales de la app val DarkBackground = Color(0xFF1A1A1A) val DarkSurface = Color(0xFF2D2D2D) val AccentGold = Color(0xFFD4AF37) val TextPrimary = Color(0xFFFFFFFF) val TextSecondary = Color(0xFFAAAAAA) val BorderColor = Color(0xFF444444)
// Colores adicionales val Purple80 = Color(0xFFD0BCFF) val PurpleGrey80 = Color(0xFFCCC2DC) val Pink80 = Color(0xFFEFB8C8)
val Purple40 = Color(0xFF6650a4) val PurpleGrey40 = Color(0xFF625b71) val Pink40 = Color(0xFF7D5260)

package com.luis.artelyapp.ui.theme
import android.app.Activity import android.os.Build import androidx.compose.foundation.isSystemInDarkTheme import androidx.compose.material3.MaterialTheme import androidx.compose.material3.darkColorScheme import androidx.compose.material3.dynamicDarkColorScheme import androidx.compose.material3.dynamicLightColorScheme import androidx.compose.material3.lightColorScheme import androidx.compose.runtime.Composable import androidx.compose.runtime.SideEffect import androidx.compose.ui.graphics.Color import androidx.compose.ui.graphics.toArgb import androidx.compose.ui.platform.LocalContext import androidx.compose.ui.platform.LocalView import androidx.core.view.WindowCompat
private val DarkColorScheme = darkColorScheme( primary = AccentGold, secondary = PurpleGrey80, tertiary = Pink80, background = DarkBackground, surface = DarkSurface, onPrimary = DarkBackground, onSecondary = TextPrimary, onTertiary = TextPrimary, onBackground = TextPrimary, onSurface = TextPrimary, )
private val LightColorScheme = lightColorScheme( primary = Purple40, secondary = PurpleGrey40, tertiary = Pink40, background = Color(0xFFFFFBFE), surface = Color(0xFFFFFBFE), onPrimary = Color.White, onSecondary = Color.White, onTertiary = Color.White, onBackground = Color(0xFF1C1B1F), onSurface = Color(0xFF1C1B1F), )
@Composable fun ArtelyAppTheme( darkTheme: Boolean = isSystemInDarkTheme(), // Dynamic color is available on Android 12+ dynamicColor: Boolean = true, content: @Composable () -> Unit ) { val colorScheme = when { dynamicColor && Build.VERSION.SDK_INT >= Build.VERSION_CODES.S -> { val context = LocalContext.current if (darkTheme) dynamicDarkColorScheme(context) else dynamicLightColorScheme(context) }
darkTheme -> DarkColorScheme else -> LightColorScheme } val view = LocalView.current if (!view.isInEditMode) { SideEffect { val window = (view.context as Activity).window window.statusBarColor = colorScheme.primary.toArgb() WindowCompat.getInsetsController(window, view).isAppearanceLightStatusBars = darkTheme } }
MaterialTheme( colorScheme = colorScheme, typography = Typography, content = content ) }
